    int choice;
    cout << "1) Circle  2) Rectangle  3) Quit" << endl;
    cout << "Choice: ";
    cin >> choice;
    cout << fixed << setprecision(2);
    switch (choice)
    {
        case 1:
        {
            double r;
            cin >> r;
            cout << "Area: " << PI * r * r << endl;
            break;
        }
        case 2:
        {
            double len, wid;
            cin >> len >> wid;
            cout << "Area: " << len * wid << endl;
            break;
        }
        case 3:
            cout << "Goodbye" << endl;
            break;
        default:
            cout << "Invalid choice" << endl;
    }
    return 0;
}

