string lower(string s)
{
    for (int i = 0; i < (int)s.size(); i++)
        s[i] = tolower(s[i]);
    return s;
}

int main()
{
    string a, b;
    cin >> a >> b;
    if (a == b)
        cout << "Same word" << endl;
    else
    {
        if (a < b)
            cout << a << " " << b << endl;
        else
            cout << b << " " << a << endl;
        if (lower(a) == lower(b))
            cout << "Different case" << endl;
    }
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main()
{
    int s1, s2, s3;
    cin >> s1 >> s2 >> s3;
    if (s1 <= 0 || s2 <= 0 || s3 <= 0)
        cout << "Invalid" << endl;
    else if (int longest = max(s1, max(s2, s3)); s1 + s2 + s3 - longest <= longest)
        cout << "Not a triangle" << endl;
    else if (s1 == s2 && s2 == s3)
        cout << "Equilateral" << endl;
    else if (s1 == s2 || s2 == s3 || s1 == s3)
        cout << "Isosceles" << endl;
    else
        cout << "Scalene" << endl;
    return 0;
}
